using System;

class A<T>
{
    [Obsolete("A<T> to T")]
    public static implicit operator T(A<T> a)
    {
        return default(T);
    }

    [Obsolete("T to A<T>")]
    public static implicit operator A<T>(T t)
    {
        return null;
    }
}


class Test
{
    static void Main()
    {
        A<int> ai = new A<int>();
        int i = ai;
        ai = i;

        // These casts don't use the UDCs (at compile time).
        A<dynamic> ad = new A<dynamic>();
        dynamic d = ad;
        ad = d;
    }
}

